-- Contact 360 normalized intelligence workspace. Applied to production via Supabase migration tool.
-- Keep this file in source control for reproducible environments.
create table if not exists public.contact_sources (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, url text not null, title text, publisher text, source_type text not null, source_date date, accessed_at timestamptz not null default now(), status text not null default 'INSPECTED' check (status in ('USED','INSPECTED','REJECTED')), evidence_strength text, why_used text, why_not_used text, claims text[] not null default '{}', created_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(contact_id,url));
create table if not exists public.contact_positions (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, company_id uuid references public.companies(id), company_name text, title text not null, department text, start_date date, end_date date, date_precision text, attribution text not null default 'PERSON_DIRECT' check (attribution in ('PERSON_DIRECT','COMPANY_CONTEXT','OPPORTUNITY_CONTEXT')), confidence numeric not null default 0.5, source_ids uuid[] not null default '{}', created_at timestamptz not null default now());
create table if not exists public.contact_education (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, institution text not null, degree text, field text, start_date date, end_date date, confidence numeric not null default 0.5, source_ids uuid[] not null default '{}', created_at timestamptz not null default now());
create table if not exists public.contact_works (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, work_type text not null, title text not null, work_date date, person_role text, company_context text, topic text, molecules text[] not null default '{}', technical_themes text[] not null default '{}', problem_addressed text, methods text, contribution text, attribution text not null default 'PERSON_DIRECT' check (attribution in ('PERSON_DIRECT','COMPANY_CONTEXT','OPPORTUNITY_CONTEXT')), confidence numeric not null default 0.5, source_ids uuid[] not null default '{}', created_at timestamptz not null default now());
create table if not exists public.contact_problems (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, problem text not null, context text, attribution text not null default 'FUNCTIONAL' check (attribution in ('DIRECT','FUNCTIONAL','COMPANY')), technical_relevance text, svak_relevance text, observed_date date, confidence numeric not null default 0.5, source_ids uuid[] not null default '{}', created_at timestamptz not null default now());
create table if not exists public.contact_themes (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, theme text not null, evidence_count integer not null default 1, first_observed date, last_observed date, confidence numeric not null default 0.5, source_ids uuid[] not null default '{}', created_at timestamptz not null default now(), unique(contact_id,theme));
create table if not exists public.contact_jtbd (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, statement text not null, category text, basis text, evidence text, confidence numeric not null default 0.5, provenance text not null default 'INFERRED' check (provenance in ('OBSERVED','INFERRED','UNKNOWN')), svak_mapping text, discovery_question text, source_ids uuid[] not null default '{}', created_at timestamptz not null default now());
create table if not exists public.contact_claims (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, claim_type text not null, claim_text text not null, provenance text not null check (provenance in ('OBSERVED','INFERRED','UNKNOWN')), confidence numeric not null default 0.5, source_ids uuid[] not null default '{}', opportunity_id uuid references public.opportunities(id), created_at timestamptz not null default now());
create table if not exists public.contact_notes (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, note_type text not null default 'NOTE', content text not null, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_by uuid references auth.users(id), updated_at timestamptz not null default now(), visibility text not null default 'INTERNAL', opportunity_id uuid references public.opportunities(id), metadata_json jsonb not null default '{}'::jsonb);
create table if not exists public.contact_history (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, entity_type text not null, entity_id uuid, field_name text not null, old_value jsonb, new_value jsonb, changed_by uuid references auth.users(id), changed_at timestamptz not null default now(), change_origin text not null default 'MANUAL' check (change_origin in ('MANUAL','AUTOMATED')), reason text, source_id uuid references public.contact_sources(id));
create table if not exists public.contact_conflicts (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, entity_type text not null, entity_id uuid, field_name text not null, manual_value jsonb, automated_value jsonb, status text not null default 'OPEN' check (status in ('OPEN','ACCEPT_AUTOMATED','KEEP_MANUAL','MERGED')), created_at timestamptz not null default now(), resolved_at timestamptz, resolved_by uuid references auth.users(id), resolution_note text);
create table if not exists public.contact_research_runs (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contacts(id) on delete cascade, status text not null default 'QUEUED' check (status in ('QUEUED','RUNNING','COMPLETED','FAILED')), started_at timestamptz, completed_at timestamptz, sources_inspected integer not null default 0, sources_used integer not null default 0, new_evidence integer not null default 0, conflicts integer not null default 0, error text, created_by uuid references auth.users(id), created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['contact_sources','contact_positions','contact_education','contact_works','contact_problems','contact_themes','contact_jtbd','contact_claims','contact_notes','contact_history','contact_conflicts','contact_research_runs'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon',t); execute format('grant select, insert, update, delete on public.%I to authenticated',t); execute format('drop policy if exists authenticated_all on public.%I',t); execute format('create policy authenticated_all on public.%I for all to authenticated using (true) with check (true)',t); end loop; end $$;
